// COMMON PARTS
const FLAT = ["               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               "];

// LEVEL BUILDER
function getLevelMap(levelIndex) {
    let parts = [];
    parts.push(FLAT, FLAT);
    if (levelIndex === 1) {
        parts.push(CUSTOM_LEVEL_1);
    } else     if (levelIndex === 2) {
        parts.push(CUSTOM_LEVEL_2);
    } else     if (levelIndex === 3) {
        parts.push(CUSTOM_LEVEL_3);
    } else     if (levelIndex === 4) {
        parts.push(CUSTOM_LEVEL_4);
    } else     if (levelIndex === 5) {
        parts.push(CUSTOM_LEVEL_5);
    }
    return joinChunks(parts);
}
